Map<String, dynamic>? _baselineCache;
Map<String, dynamic> get _baseline =>
    _baselineCache ??= Map<String, dynamic>.from(
      jsonDecode(
            utf8.decode(gzip.decode(base64Decode(_compiledBaselineBase64))),
          )
          as Map,
    );
final _fontFamilies = <String>{};
final _layoutCounts = <String, int>{};
var _verifiedPages = 0;

Object? _canonical(Object? value) {
  if (value is Map) {
    final keys = value.keys.cast<String>().toList()..sort();
    return {for (final key in keys) key: _canonical(value[key])};
  }
  if (value is List) return value.map(_canonical).toList();
  return value;
}

String _digest(Object? value) =>
    sha256.convert(utf8.encode(jsonEncode(_canonical(value)))).toString();
String _words(Object? value) =>
    (value?.toString() ?? '').replaceAll(RegExp(r'\s+'), ' ').trim();
String _characters(Object? value) =>
    (value?.toString() ?? '').replaceAll(RegExp(r'\s+'), '');

({String source, String display})? _verticalTitle(Map layer) {
  final id = '${layer['id']}';
  if (RegExp(
    r'^shared-seasons_(portrait|square|landscape)_11_part_2$',
  ).hasMatch(id)) {
    return (source: '비\n오\n는\n주\n말', display: '비 오는 주말');
  }
  if (RegExp(
    r'^little-companion_(portrait|square|landscape)_11_part_4$',
  ).hasMatch(id)) {
    return (source: '간\n식\n시\n간', display: '간식 시간');
  }
  return null;
}

String _displayWords(Map layer) {
  final contract = _verticalTitle(layer);
  if (contract == null || !layer.containsKey('editorialSourceText')) {
    return _words(layer['text']);
  }
  // Only these six historically vertical headings change word spacing. Keep
  // the exact original source and compare its canonical baseline display hash.
  expect(
    layer['editorialSourceText'],
    contract.source,
    reason: '${layer['id']}',
  );
  expect(_words(layer['text']), contract.display, reason: '${layer['id']}');
  expect(
    _characters(layer['text']),
    _characters(contract.source),
    reason: '${layer['id']}: unchanged original characters and order',
  );
  return _words(contract.source);
}

Future<void> loadPaidEditorialFonts() async {
  final manifest =
      jsonDecode(await rootBundle.loadString('FontManifest.json')) as List;
  for (final raw in manifest.whereType<Map>()) {
    final loader = FontLoader(raw['family'] as String);
    for (final font in (raw['fonts'] as List).whereType<Map>()) {
      loader.addFont(rootBundle.load(font['asset'] as String));
    }
    await loader.load();
    _fontFamilies.add(raw['family'] as String);
  }
}

class PaidEditorialBook {
  PaidEditorialBook(this.template, this.count, this.aspect);
  final PremiumTemplate template;
  final int count;
  final CollectionAspect aspect;
  Map<String, dynamic>? _document;
  Map<String, dynamic> get document => _document ??= _build();
  String get productKey => pointShopTemplateKey(template);
  String get key => '${template.id}/$count/${aspect.name}';
  Map<String, dynamic> _build() {
    final volume = publishedPremiumVolume(template.id);
    final catalog = volume == null
        ? Map<String, dynamic>.from(jsonDecode(template.templateJson!) as Map)
        : premiumCatalogDocument(volume, innerPages: count);
    return Map<String, dynamic>.from(
      (catalog['variants'] as Map)[aspect.name] as Map,
    );
  }
}

Iterable<PaidEditorialBook> paidEditorialBooks() sync* {
  for (final template in publishedPremiumTemplates) {
    final volume = publishedPremiumVolume(template.id);
    for (final count in volume?.pageCounts ?? [template.pageCount]) {
      for (final aspect in CollectionAspect.values) {
        yield PaidEditorialBook(template, count, aspect);
      }
    }
  }
}

Map<String, dynamic> _metadata(Map<String, dynamic> document) => {
  for (final entry in document.entries)
    if (!const {
      'cover',
      'pages',
      'variants',
      'coverRevision',
      'coverReview',
      'qualityRevision',
      'editorialRevision',
      'interiorQualityRevision',
      'typographyRevision',
      'samplePhotoRevision',
      'artDirection',
      'layoutSafety',
    }.contains(entry.key))
      entry.key: entry.value,
};

Map<String, dynamic> _identity(PaidEditorialBook book) => {
  'catalogId': book.template.id,
  'productKey': book.productKey,
  'points': pointShopLaunchPrices[book.productKey]!.points,
  'premium': book.template.isPremium,
  'title': book.template.title,
  'subtitle': book.template.subTitle,
  'description': book.template.description,
  'category': book.template.category,
  'catalogPageCount': book.template.pageCount,
  'tags': book.template.tags,
  'selectedInnerPages': book.count,
  'metadata': {
    for (final key in _metadata(_rawDocument(book)).keys)
      if (book.document.containsKey(key)) key: book.document[key],
  },
};

Map<String, dynamic> _rawDocument(PaidEditorialBook book) {
  final volume = publishedPremiumVolume(book.template.id);
  if (volume != null)
    return volume.document(book.aspect, innerPages: book.count);
  for (final entry in conceptVolumeCatalogIds.entries) {
    if (entry.value == book.template.id) return entry.key.document(book.aspect);
  }
  for (final edition in AtelierEdition.values) {
    if (edition.catalogId == book.template.id)
      return edition.document(book.aspect);
  }
  return StudioEdition.values
      .singleWhere((e) => e.premium && e.catalogId == book.template.id)
      .document(book.aspect);
}

Map<String, dynamic> _sources(Map layer) => {
  for (final key in const ['imageUrl', 'originalUrl', 'previewUrl'])
    if (layer.containsKey(key)) key: layer[key],
};
Map<String, dynamic> _visual(Map layer) => {
  for (final key in const [
    'id',
    'type',
    'x',
    'y',
    'w',
    'h',
    'rotation',
    'frame',
    'align',
    'style',
    'fillColor',
    'opacity',
    'cornerRadius',
    'fontFamily',
    'fontSize',
    'fontWeight',
    'lineHeight',
  ])
    if (layer.containsKey(key)) key: layer[key],
};
Map<String, dynamic> _pageRecord(Map<String, dynamic> page) {
  final layers = (page['layers'] as List).cast<Map>();
  return {
    'page': _digest(page),
    'visual': _digest(layers.map(_visual).toList()),
    'ids': {for (final layer in layers) layer['id'] as String: layer['type']},
    'text': {
      for (final layer in layers.where((l) => l['type'] == 'text'))
        layer['id'] as String: {
          'exact': _digest(layer['editorialSourceText'] ?? layer['text']),
          'words': _digest(
            _words(layer['editorialSourceText'] ?? layer['text']),
          ),
          'display': _digest(_displayWords(layer)),
        },
    },
    'photos': {
      for (final layer in layers.where((l) => l['type'] == 'image'))
        layer['id'] as String: _digest(_sources(layer)),
    },
  };
}

Map<String, dynamic> _rawBooks() => {
  'premium': {
    for (final volume in PremiumVolume.values)
      volume.id: {
        for (final count in volume.pageCounts)
          count.toString(): {
            for (final aspect in CollectionAspect.values)
              aspect.name: volume.document(aspect, innerPages: count),
          },
      },
  },
  'concept': {
    for (final volume in ConceptVolume.values)
      volume.id: {
        for (final aspect in CollectionAspect.values)
          aspect.name: volume.document(aspect),
      },
  },
  'atelier': {
    for (final edition in AtelierEdition.values)
      edition.id: {
        for (final aspect in CollectionAspect.values)
          aspect.name: edition.document(aspect),
      },
  },
  'studio': {
    for (final edition in StudioEdition.values.where((e) => e.premium))
      edition.id: {
        for (final aspect in CollectionAspect.values)
          aspect.name: edition.document(aspect),
      },
  },
};
String _freeDigest() => _digest({
  for (final collection in authoredCollections)
    collection.id: {
      'catalogId': collection.bundledId,
      'productKey': pointShopAuthoredTemplateKey(collection),
      'points': pointShopLaunchPrices[pointShopAuthoredTemplateKey(collection)]!
          .points,
      'variants': {
        for (final aspect in CollectionAspect.values)
          aspect.name: collection.document(aspect),
      },
    },
});

Map<String, dynamic> _recordBaseline() {
  final books = paidEditorialBooks().toList();
  return {
    'schema': 1,
    'rawPaid': _digest(_rawBooks()),
    'free': _freeDigest(),
    'books': {
      for (final book in books)
        book.key: {
          'identity': _digest(_identity(book)),
          'pages': [
            for (final page in templateDocumentPages(book.document))
              _pageRecord(page),
          ],
        },
    },
    'catalogs': {
      for (final template in publishedPremiumTemplates)
        template.id.toString(): _digest(jsonDecode(template.templateJson!)),
    },
  };
}

String _sourceDigest(Map<String, dynamic> page) {
  final record = _pageRecord(page);
  return _digest({
    'ids': {
      for (final e in (record['ids'] as Map).entries)
        if (e.value == 'image' || e.value == 'text') e.key as String: e.value,
    },
    'text': record['text'],
    'photos': record['photos'],
  });
}

String _photoOrder(Map<String, dynamic> page) => _digest([
  for (final layer in (page['layers'] as List).cast<Map>())
    if (layer['type'] == 'image') layer['id'],
]);

Rect _rect(LayerModel layer) =>
    layer.position & Size(layer.width, layer.height);
Rect _paintBounds(LayerModel layer) {
  final angle = layer.rotation * math.pi / 180;
  return Rect.fromCenter(
    center: _rect(layer).center,
    width:
        layer.width * math.cos(angle).abs() +
        layer.height * math.sin(angle).abs(),
    height:
        layer.width * math.sin(angle).abs() +
        layer.height * math.cos(angle).abs(),
  );
}

bool _contains(Rect outer, Rect inner) =>
    outer.left <= inner.left + .5 &&
    outer.top <= inner.top + .5 &&
    outer.right >= inner.right - .5 &&
    outer.bottom >= inner.bottom - .5;
Color? _paper(List<LayerModel> layers, int index, Rect ink) {
  for (final behind in layers.take(index).toList().reversed) {
    if (!_rect(behind).overlaps(ink)) continue;
    if (behind.type == LayerType.image ||
        (behind.type == LayerType.sticker && behind.hasImageSource))
      return null;
    final fill = behind.decorationFillColor;
    if (fill == null || behind.opacity != 1 || !_contains(_rect(behind), ink))
      continue;
    final hex = fill.replaceFirst('#', '');
    final color = Color(int.parse(hex.length == 6 ? 'FF$hex' : hex, radix: 16));
    if (color.a == 1) return color;
  }
  return null;
}

LayerModel _roundTrip(LayerModel layer, PaidEditorialBook book, bool cover) =>
    LayerExportMapper.fromJson(
      Map<String, dynamic>.from(
        jsonDecode(
              jsonEncode(
                LayerExportMapper.toJson(
                  layer,
                  canvasSize: book.aspect.canvas,
                  isCover: cover,
                ),
              ),
            )
            as Map,
      ),
      canvasSize: book.aspect.canvas,
      isCover: cover,
    );

void _inspectPage(
  PaidEditorialBook book,
  Map<String, dynamic> page,
  Map<String, dynamic> original,
  int index,
) {
  final canvas = book.aspect.canvas;
  final layers = DataTemplateEngine.buildLayersFromJson(page, canvas);
  final raw = {
    for (final l in (page['layers'] as List).cast<Map>()) l['id']: l,
  };
  final before = {
    for (final l in (original['layers'] as List).cast<Map>()) l['id']: l,
  };
  final photos = layers.where((l) => l.type == LayerType.image).toList();
  final beforePhotos = {
    for (final l in DataTemplateEngine.buildLayersFromJson(original, canvas))
      if (l.type == LayerType.image) l.id: l,
  };
  final inkBounds = <String, Rect>{};
  final cleared = AlbumCreationTemplate.preparePages(
    [layers],
    sourceCanvas: canvas,
    cover: book.aspect.cover,
  ).single;
  expect(
    layers.map((l) => l.id).toSet(),
    hasLength(layers.length),
    reason: book.key,
  );
  if (index == 0) {
    expect(page['coverTypographyTreatment'], 'direct-on-photograph');
    expect(page['typographyPanelCoverageFraction'], 0);
    expect(photos, isNotEmpty, reason: '${book.key}: real cover subject');
    expect(
      photos.map((l) => l.width * l.height).fold<double>(0, math.max) /
          (canvas.width * canvas.height),
      closeTo(1, .0001),
      reason: book.key,
    );
    final heroIndex = layers.indexWhere(
      (layer) =>
          layer.type == LayerType.image &&
          layer.width * layer.height >= canvas.width * canvas.height * .9999,
    );
    expect(heroIndex, greaterThanOrEqualTo(0), reason: book.key);
    for (final foreground in layers.skip(heroIndex + 1)) {
      expect(
        foreground.type,
        anyOf(LayerType.image, LayerType.text),
        reason:
            '${book.key}/${foreground.id}: no title plate, scrim or gradient '
            'may obscure the photograph',
      );
    }
  }
  for (final (i, layer) in layers.indexed) {
    final label = '${book.key}/$index/${layer.id}';
    final rect = _rect(layer), painted = _paintBounds(layer);
    expect(rect.isFinite, isTrue, reason: label);
    expect(rect.width, greaterThan(0), reason: label);
    expect(rect.height, greaterThan(0), reason: label);
    expect(painted.left, greaterThanOrEqualTo(-.5), reason: label);
    expect(painted.top, greaterThanOrEqualTo(-.5), reason: label);
    expect(painted.right, lessThanOrEqualTo(canvas.width + .5), reason: label);
    expect(
      painted.bottom,
      lessThanOrEqualTo(canvas.height + .5),
      reason: label,
    );
    final saved = _roundTrip(layer, book, index == 0);
    expect(saved.id, layer.id, reason: label);
    expect(saved.type, layer.type, reason: label);
    expect(saved.position.dx, closeTo(layer.position.dx, .001), reason: label);
    expect(saved.position.dy, closeTo(layer.position.dy, .001), reason: label);
    expect(saved.width, closeTo(layer.width, .001), reason: label);
    expect(saved.height, closeTo(layer.height, .001), reason: label);
    expect(saved.rotation, layer.rotation, reason: label);
    expect(saved.opacity, layer.opacity, reason: label);
    if (layer.type == LayerType.image) {
      final source = beforePhotos[layer.id]!;
      final oldOffset = Offset(
        (source.imageOffset?.dx ?? 0) / source.width,
        (source.imageOffset?.dy ?? 0) / source.height,
      );
      final offset = Offset(
        (layer.imageOffset?.dx ?? 0) / layer.width,
        (layer.imageOffset?.dy ?? 0) / layer.height,
      );
      expect(layer.imageZoom, source.imageZoom, reason: '$label: source zoom');
      final familyPortraitCrop =
          book.template.id == -9532 &&
          book.count == 32 &&
          book.aspect == CollectionAspect.portrait &&
          index == 0 &&
          layer.id == 'summer-keepsake-box_portrait_0_cover_photo' &&
          layer.imageUrl ==
              'asset:assets/templates/atelier_editions_2026/summer-keepsake-box.png';
      for (final field in const [
        'imageZoom',
        'imageOffsetRatio',
        'imageOffset',
        'imageTemplate',
      ]) {
        if (familyPortraitCrop && field == 'imageOffsetRatio') continue;
        expect(
          raw[layer.id]![field],
          before[layer.id]![field],
          reason: '$label: exact source $field',
        );
      }
      if (familyPortraitCrop) {
        expect(raw[layer.id]!['imageOffsetRatio'], {'x': .16, 'y': 0.0});
        expect(raw[layer.id]!['sourcePhotoTransform'], {
          'imageOffsetRatio': before[layer.id]!['imageOffsetRatio'],
          'imageOffset': before[layer.id]!['imageOffset'],
          'imageZoom': before[layer.id]!['imageZoom'] ?? 1.0,
        });
        expect(
          oldOffset,
          Offset.zero,
          reason: '$label: approved original offset',
        );
        expect(
          offset.dx,
          closeTo(.16, .000001),
          reason: '$label: approved face-safe crop',
        );
        expect(offset.dy, closeTo(0, .000001), reason: label);
      } else {
        expect(
          raw[layer.id]!['sourcePhotoTransform'],
          before[layer.id]!['sourcePhotoTransform'],
          reason: '$label: no unapproved source-transform exception',
        );
        expect(
          offset.dx,
          closeTo(oldOffset.dx, .000001),
          reason: '$label: source crop x',
        );
        expect(
          offset.dy,
          closeTo(oldOffset.dy, .000001),
          reason: '$label: source crop y',
        );
      }
      expect(saved.imageUrl, layer.imageUrl, reason: label);
      expect(saved.imageZoom, layer.imageZoom, reason: label);
      expect(
        saved.imageOffset?.dx ?? 0,
        closeTo(layer.imageOffset?.dx ?? 0, .001),
        reason: label,
      );
      expect(
        saved.imageOffset?.dy ?? 0,
        closeTo(layer.imageOffset?.dy ?? 0, .001),
        reason: label,
      );
      expect(cleared[i].hasImageSource, isFalse, reason: label);
      expect(
        _roundTrip(
          cleared[i].copyWith(imageUrl: 'asset:assets/snapfit_home_square.jpg'),
          book,
          index == 0,
        ).imageUrl,
        'asset:assets/snapfit_home_square.jpg',
      );
    }
    if (layer.type != LayerType.text) continue;
    expect(saved.text, layer.text, reason: label);
    expect(
      saved.textStyle!.fontFamily,
      layer.textStyle!.fontFamily,
      reason: label,
    );
    expect(_fontFamilies, contains(layer.textStyle!.fontFamily), reason: label);
    expect(
      layer.textFillMode?.trim().toLowerCase(),
      anyOf(isNull, '', 'solid', 'none'),
      reason: label,
    );
    final role = raw[layer.id]!['typographyRole'] as String?;
    expect(role, isNotNull, reason: '$label: semantic type role');
    expect(
      layer.textStyle!.fontSize,
      greaterThanOrEqualTo(role == 'body' ? 11 : 8.5),
      reason: label,
    );
    final measure = TextPainter(
      text: TextSpan(text: layer.text, style: layer.textStyle),
      textAlign: layer.textAlign ?? TextAlign.left,
      textDirection: TextDirection.ltr,
      strutStyle: StrutStyle.fromTextStyle(
        layer.textStyle!,
        forceStrutHeight: true,
      ),
    )..layout(maxWidth: layer.width);
    final lines = measure.computeLineMetrics();
    expect(
      measure.height,
      lessThanOrEqualTo(layer.height + .5),
      reason: '$label: font fit',
    );
    expect(
      lines.every((l) => l.width <= layer.width + .5),
      isTrue,
      reason: '$label: line width',
    );
    final width = lines.fold<double>(
      0,
      (value, line) => math.max(value, line.width),
    );
    final dx = switch (layer.textAlign) {
      TextAlign.right || TextAlign.end => layer.width - width,
      TextAlign.center => (layer.width - width) / 2,
      _ => 0.0,
    };
    final ink = Rect.fromLTWH(rect.left + dx, rect.top, width, measure.height);
    measure.dispose();
    if ((layer.text ?? '').trim().isNotEmpty) inkBounds[layer.id] = ink;
    final originalLayer = before[layer.id];
    if (originalLayer != null) {
      final source =
          '${originalLayer['editorialSourceText'] ?? originalLayer['text'] ?? ''}';
      expect(
        _characters(layer.text),
        _characters(source),
        reason: '$label: original characters and order',
      );
      final paragraphBreaks = RegExp(r'\n[ \t]*\n').allMatches(source).length;
      expect(
        RegExp(r'\n[ \t]*\n').allMatches(layer.text ?? '').length,
        greaterThanOrEqualTo(paragraphBreaks),
        reason: '$label: original paragraph boundaries',
      );
    }
    if (index > 0) {
      expect(
        rect.left,
        greaterThanOrEqualTo((index.isEven ? 30 : 20) - .5),
        reason: label,
      );
      expect(
        rect.right,
        lessThanOrEqualTo(canvas.width - (index.isOdd ? 30 : 20) + .5),
        reason: label,
      );
      expect(rect.top, greaterThanOrEqualTo(11.5), reason: label);
      expect(
        rect.bottom,
        lessThanOrEqualTo(canvas.height - 11.5),
        reason: label,
      );
      for (final photo in photos) {
        expect(
          ink.deflate(.5).overlaps(_rect(photo).deflate(.5)),
          isFalse,
          reason: '$label: ink overlaps photo ${photo.id}',
        );
      }
    }
    if (index == 0 && (layer.text ?? '').trim().isNotEmpty) {
      // This release deliberately removes the opaque cover surfaces. Cover
      // legibility is checked against real decoded photographs in RAM; a
      // fictitious flat paper color must not make this test claim AA contrast.
      expect(
        _paper(layers, i, ink),
        isNull,
        reason: '$label: direct photograph typography has no backing panel',
      );
      final shadows = layer.textStyle!.shadows ?? const <Shadow>[];
      final savedShadows = saved.textStyle!.shadows ?? const <Shadow>[];
      expect(shadows.length, lessThanOrEqualTo(1), reason: label);
      expect(layer.textStyle!.background, isNull, reason: label);
      expect(layer.textStyle!.backgroundColor, isNull, reason: label);
      expect(savedShadows, hasLength(shadows.length), reason: label);
      for (final (shadowIndex, shadow) in shadows.indexed) {
        expect(shadow.color.a, lessThanOrEqualTo(.4), reason: label);
        expect(shadow.blurRadius, inInclusiveRange(0, 2.5), reason: label);
        expect(shadow.offset.distance, lessThanOrEqualTo(1), reason: label);
        expect(savedShadows[shadowIndex].color, shadow.color, reason: label);
        expect(
          savedShadows[shadowIndex].blurRadius,
          closeTo(shadow.blurRadius, .001),
          reason: label,
        );
        expect(
          savedShadows[shadowIndex].offset.dx,
          closeTo(shadow.offset.dx, .001),
          reason: label,
        );
        expect(
          savedShadows[shadowIndex].offset.dy,
          closeTo(shadow.offset.dy, .001),
          reason: label,
        );
      }
    } else if ((layer.text ?? '').trim().isNotEmpty) {
      final paper = _paper(layers, i, ink);
      expect(paper, isNotNull, reason: '$label: known photo-safe ink surface');
      if (paper != null) {
        final a = Color.alphaBlend(
          layer.textStyle!.color!,
          paper,
        ).computeLuminance();
        final b = paper.computeLuminance();
        expect(
          (math.max(a, b) + .05) / (math.min(a, b) + .05),
          greaterThanOrEqualTo(4.5),
          reason: label,
        );
      }
    }
  }
  final text = inkBounds.entries.toList();
  for (var a = 0; a < text.length; a++) {
    for (var b = a + 1; b < text.length; b++) {
      expect(
        text[a].value.deflate(.75).overlaps(text[b].value.deflate(.75)),
        isFalse,
        reason:
            '${book.key}/$index: ink overlaps ${text[a].key} / ${text[b].key}',
      );
    }
  }
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  setUpAll(loadPaidEditorialFonts);
  if (_record) {
    test(
      'record all paid editions and the unchanged free catalog before refinement',
      () {
        expect(publishedPremiumTemplates, hasLength(26));
        expect(authoredCollections, hasLength(42));
        if (File(_baselinePath).existsSync())
          throw StateError('Refusing to overwrite $_baselinePath');
        final baseline = _recordBaseline();
        final bytes = utf8.encode(jsonEncode(baseline));
        File(_baselinePath).writeAsBytesSync(bytes);
        // Only IDs, types and fixed hashes are saved, never text bodies or images.
        // ignore: avoid_print
        print(
          'SNAPFIT_PAID_EDITORIAL_BASELINE_V1:${jsonEncode({'path': _baselinePath, 'bytes': bytes.length, 'sha256': _digest(baseline), 'products': 26, 'books': (baseline['books'] as Map).length, 'pages': (baseline['books'] as Map).values.fold<int>(0, (total, book) => total + ((book as Map)['pages'] as List).length), 'freeProtected': 42})}',
        );
      },
    );
    return;
  }
  test(
    'raw paid factories and all 42 free product identities and prices stay fixed',
    () {
      expect(_digest(_rawBooks()), _baseline['rawPaid']);
      expect(publishedPremiumTemplates, hasLength(26));
      expect(authoredCollections, hasLength(42));
      // The user authorized all 68 covers to change. The companion free
      // editorial quality suite retains its existing per-inner-page baseline;
      // do not re-record that fixture or replace it with the new cover hash.
      const freeProducts = {
        -9301: 'template:lightbound',
        -9302: 'template:journey',
        -9303: 'template:small-days',
        -9401: 'template:our-vows',
        -9402: 'template:garden-promise',
        -9403: 'template:one-fine-film',
        -9404: 'template:love-letters',
        -9411: 'template:across-the-sea',
        -9412: 'template:city-collector',
        -9413: 'template:slow-paths',
        -9414: 'template:travel-postbox',
        -9421: 'template:seasonal-table',
        -9422: 'template:taste-archive',
        -9423: 'template:better-together',
        -9424: 'template:weekend-temperature',
        -9431: 'template:your-first-year',
        -9432: 'template:little-footsteps',
        -9433: 'template:you-are-spring',
        -9434: 'template:growing-in-color',
        -9435: 'template:first-birthday',
        -9441: 'template:our-family-year',
        -9442: 'template:around-our-table',
        -9443: 'template:our-good-company',
        -9444: 'template:across-generations',
        -9445: 'template:a-picnic-together',
        -9451: 'template:dates-of-us',
        -9452: 'template:scenes-for-two',
        -9453: 'template:seasons-of-love',
        -9454: 'template:still-us',
        -9455: 'template:collected-by-two',
        -9461: 'template:a-day-with-you',
        -9462: 'template:shapes-of-naps',
        -9463: 'template:our-walking-promise',
        -9464: 'template:our-little-companion',
        -9465: 'template:the-kindest-face',
        -9304: 'template:wind-atlas',
        -9305: 'template:our-prose',
        -9471: 'template:alley-afternoon',
        -9472: 'template:saturday-together',
        -9473: 'template:daily-paw-walk',
        -9474: 'template:our-first-promise',
        -9475: 'template:little-day-discoveries',
      };
      expect({
        for (final collection in authoredCollections)
          collection.bundledId: pointShopAuthoredTemplateKey(collection),
      }, freeProducts);
      expect(bundledCreationTemplates, hasLength(freeProducts.length));
      for (final template in bundledCreationTemplates) {
        final productKey = pointShopTemplateKey(template);
        expect(productKey, freeProducts[template.id]);
        expect(template.isPremium, isFalse);
        expect(pointShopLaunchPrices[productKey]!.points, 0);
      }
    },
  );
  test(
    'the sole family portrait crop retains all four original faces',
    () async {
      final book = paidEditorialBooks().singleWhere(
        (book) =>
            book.template.id == -9532 &&
            book.count == 32 &&
            book.aspect == CollectionAspect.portrait,
      );
      final page = templateDocumentPages(book.document).first;
      final photo =
          DataTemplateEngine.buildLayersFromJson(
            page,
            book.aspect.canvas,
          ).singleWhere(
            (layer) => layer.id == 'summer-keepsake-box_portrait_0_cover_photo',
          );
      expect(photo.imageZoom, 1);
      expect(photo.rotation, 0);
      expect(photo.imageAlignment.x, closeTo(.32, .000001));
      expect(photo.imageAlignment.y, 0);
      final bytes = await rootBundle.load(
        'assets/templates/atelier_editions_2026/summer-keepsake-box.png',
      );
      final codec = await ui.instantiateImageCodec(bytes.buffer.asUint8List());
      final image = (await codec.getNextFrame()).image;
      try {
        final source = Size(image.width.toDouble(), image.height.toDouble());
        final fitted = applyBoxFit(
          BoxFit.cover,
          source,
          Size(photo.width, photo.height),
        );
        final visible = photo.imageAlignment.inscribe(
          fitted.source,
          Offset.zero & source,
        );
        final normalized = Rect.fromLTRB(
          visible.left / source.width,
          visible.top / source.height,
          visible.right / source.width,
          visible.bottom / source.height,
        );
        // Source-normalized face and hat bounds, reviewed in the original image.
        const faces = {
          'father': Rect.fromLTWH(.398, .386, .064, .095),
          'child': Rect.fromLTWH(.488, .551, .068, .080),
          'mother': Rect.fromLTWH(.592, .425, .075, .095),
          'right family member': Rect.fromLTWH(.725, .410, .071, .090),
        };
        for (final face in faces.entries) {
          expect(
            normalized.contains(face.value.topLeft) &&
                normalized.contains(face.value.bottomRight),
            isTrue,
            reason: '${face.key}: ${face.value} must remain inside $normalized',
          );
        }
      } finally {
        image.dispose();
        codec.dispose();
      }
    },
  );
  test('two original vertical headings become complete horizontal phrases', () {
    var verified = 0;
    for (final book in paidEditorialBooks().where(
      (book) => const {-9516, -9517}.contains(book.template.id),
    )) {
      for (final page in templateDocumentPages(book.document)) {
        for (final layer in (page['layers'] as List).cast<Map>()) {
          final contract = _verticalTitle(layer);
          if (contract == null) continue;
          expect(layer['editorialSourceText'], contract.source);
          expect(_words(layer['text']), contract.display);
          expect(_characters(layer['text']), _characters(contract.source));
          verified++;
        }
      }
    }
    expect(verified, 6);
  });
  test('Luminous opening headings retain a body headline hierarchy', () {
    var verified = 0;
    for (final book in paidEditorialBooks().where(
      (book) => book.template.id == -9502,
    )) {
      final page = templateDocumentPages(book.document)[2];
      final id = 'luminous-edition_${book.aspect.name}_2_folio_heading';
      final raw = (page['layers'] as List).cast<Map>().singleWhere(
        (layer) => layer['id'] == id,
      );
      final layers = DataTemplateEngine.buildLayersFromJson(
        page,
        book.aspect.canvas,
      );
      final layer = layers.singleWhere((layer) => layer.id == id);
      expect(raw['editorialTextRole'], 'headline', reason: book.key);
      expect(raw['typographyRole'], 'body', reason: book.key);
      expect(
        layer.textStyle!.fontSize,
        greaterThanOrEqualTo(22),
        reason: book.key,
      );
      expect(
        _rect(layer).bottom,
        lessThan(book.aspect.canvas.height - 60),
        reason: '${book.key}: headline stays above the footer region',
      );
      final folios = layers.where(
        (layer) => RegExp(
          r'_(folio|folio_label|folio_number|folio_date)$',
        ).hasMatch(layer.id),
      );
      expect(folios, isNotEmpty, reason: '${book.key}: actual page folio');
      for (final folio in folios) {
        expect(
          _rect(folio).top - _rect(layer).bottom,
          greaterThanOrEqualTo(24),
          reason: '${book.key}: headline and ${folio.id} have separate regions',
        );
      }
      verified++;
    }
    expect(verified, 6); // All three aspects and both 24/36-page editions.
  });
  for (final book in paidEditorialBooks()) {
    test(
      '${book.key}: every paid page preserves content and passes visual preflight',
      () {
        final before = (_baseline['books'] as Map)[book.key] as Map;
        expect(_digest(_identity(book)), before['identity'], reason: book.key);
        expect(book.template.isPremium, isTrue);
        final pages = templateDocumentPages(book.document);
        final sourcePages = templateDocumentPages(_rawDocument(book));
        final original = before['pages'] as List;
        expect(pages, hasLength(book.count + 1), reason: book.key);
        expect(pages, hasLength(original.length), reason: book.key);
        for (final (index, page) in pages.indexed) {
          final hashes = original[index] as List;
          expect(
            _sourceDigest(page),
            hashes[2],
            reason:
                '${book.key}/$index: source IDs and full text/photo content',
          );
          expect(
            _photoOrder(page),
            hashes[3],
            reason: '${book.key}/$index: original photograph sequence',
          );
          expect(
            _pageRecord(page)['visual'],
            isNot(hashes[1]),
            reason: '${book.key}/$index: actual visual refinement',
          );
          _inspectPage(book, page, sourcePages[index], index);
          _verifiedPages++;
          if (index > 0) {
            final layout = page['editorialLayout'] as String?;
            expect(layout, isNotNull, reason: '${book.key}/$index');
            _layoutCounts.update(
              layout!,
              (value) => value + 1,
              ifAbsent: () => 1,
            );
          }
        }
      },
    );
  }
  test(
    'all 26 published catalogs expose the new artwork and complete coverage',
    () {
      expect(paidEditorialBooks().length, 93);
      expect(_verifiedPages, 2757);
      for (final template in publishedPremiumTemplates) {
        expect(
          _digest(jsonDecode(template.templateJson!)),
          isNot((_baseline['catalogs'] as Map)[template.id.toString()]),
          reason: template.title,
        );
      }
      expect(
        _layoutCounts.values.fold<int>(0, (sum, value) => sum + value),
        2664,
      );
      // ignore: avoid_print
      print(
        'SNAPFIT_PAID_EDITORIAL_QUALITY_METRICS_V1:${jsonEncode({'products': 26, 'editionChoices': 31, 'books': 93, 'pages': _verifiedPages, 'covers': 93, 'interiors': 2664, 'protectedFreeProducts': 42, 'layoutCounts': _layoutCounts})}',
      );
    },
  );
}
